// t20_sfu -- generated by gen_t20_sfu.py; do not edit by hand.
// ISA sec 8.8. Bounds from tools/model/gen_sfu_vectors.py (60-digit decimal).
.org 0
start:
    // ---- v.exp2.approx : every lane inside the 2^-22 band ----
    .li      s1, #x_exp2
    .li      s2, #lo_exp2
    .li      s3, #hi_exp2
    v.ld.w   v1, [s1, #0]
    v.ld.w   v2, [s2, #0]
    v.ld.w   v3, [s3, #0]
    v.exp2.approx v4, v1
    vf.cmp.ge p1, v4, v2
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #1
    vf.cmp.le p1, v4, v3
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #2

    // ---- v.log2.approx : every lane inside the 2^-22 band ----
    .li      s1, #x_log2
    .li      s2, #lo_log2
    .li      s3, #hi_log2
    v.ld.w   v1, [s1, #0]
    v.ld.w   v2, [s2, #0]
    v.ld.w   v3, [s3, #0]
    v.log2.approx v4, v1
    vf.cmp.ge p1, v4, v2
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #3
    vf.cmp.le p1, v4, v3
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #4

    // ---- v.rcp.approx : every lane inside the 2^-22 band ----
    .li      s1, #x_rcp
    .li      s2, #lo_rcp
    .li      s3, #hi_rcp
    v.ld.w   v1, [s1, #0]
    v.ld.w   v2, [s2, #0]
    v.ld.w   v3, [s3, #0]
    v.rcp.approx v4, v1
    vf.cmp.ge p1, v4, v2
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #5
    vf.cmp.le p1, v4, v3
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #6

    // ---- v.rsqrt.approx : every lane inside the 2^-22 band ----
    .li      s1, #x_rsqrt
    .li      s2, #lo_rsqrt
    .li      s3, #hi_rsqrt
    v.ld.w   v1, [s1, #0]
    v.ld.w   v2, [s2, #0]
    v.ld.w   v3, [s3, #0]
    v.rsqrt.approx v4, v1
    vf.cmp.ge p1, v4, v2
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #7
    vf.cmp.le p1, v4, v3
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #8

    // ---- sec 8.8 special values: specified exactly, so checked exactly --
    .li      s1, #x_spec
    v.ld.w   v1, [s1, #0]
    v.rcp.approx v4, v1
    .assert_lane v4, #0, #0x7f800000, #9   // rcp(+0) = +inf
    .assert_lane v4, #1, #0xff800000, #10   // rcp(-0) = -inf
    .assert_lane v4, #2, #0x00000000, #11   // rcp(+inf) = +0
    .assert_lane v4, #3, #0x80000000, #12   // rcp(-inf) = -0
    .assert_lane v4, #4, #0x7f800000, #13   // subnormal flushed to +0 first
    .assert_lane v4, #5, #0xff800000, #14   // subnormal flushed to -0 first
    .assert_lane v4, #6, #0x3f800000, #15   // rcp(1) = 1
    .assert_lane v4, #7, #0x3e800000, #16   // rcp(4) = 0.25
    v.exp2.approx v4, v1
    .assert_lane v4, #0, #0x3f800000, #17   // exp2(+0) = 1
    .assert_lane v4, #1, #0x3f800000, #18   // exp2(-0) = 1
    .assert_lane v4, #2, #0x7f800000, #19   // exp2(+inf) = +inf
    .assert_lane v4, #3, #0x00000000, #20   // exp2(-inf) = +0
    .assert_lane v4, #4, #0x3f800000, #21   // subnormal flushed to zero first
    .assert_lane v4, #5, #0x3f800000, #22   // subnormal flushed to zero first
    v.log2.approx v4, v1
    .assert_lane v4, #0, #0xff800000, #23   // log2(+0) = -inf
    .assert_lane v4, #1, #0xff800000, #24   // log2(-0) = -inf
    .assert_lane v4, #2, #0x7f800000, #25   // log2(+inf) = +inf
    .assert_lane v4, #4, #0xff800000, #26   // subnormal flushed to zero first
    .assert_lane v4, #6, #0x00000000, #27   // log2(1) = +0
    .assert_lane v4, #7, #0x40000000, #28   // log2(4) = 2
    v.rsqrt.approx v4, v1
    .assert_lane v4, #0, #0x7f800000, #29   // rsqrt(+0) = +inf
    .assert_lane v4, #2, #0x00000000, #30   // rsqrt(+inf) = +0
    .assert_lane v4, #6, #0x3f800000, #31   // rsqrt(1) = 1
    .assert_lane v4, #7, #0x3f000000, #32   // rsqrt(4) = 0.5

    // ---- a masked SFU write leaves the inactive lanes alone -------------
    .li      s1, #x_rcp
    .li      s2, #lo_rcp
    .li      s3, #hi_rcp
    v.ld.w   v1, [s1, #0]
    v.ld.w   v2, [s2, #0]
    v.ld.w   v3, [s3, #0]
    .li      s5, #0x0f0f
    p.frombits p5, s5
    v.movi   v6, #7
    @p5 v.rcp.approx v6, v1
    .assert_lane v6, #4, #7, #33      // masked off, untouched
    .assert_lane v6, #5, #7, #34      // masked off, untouched
    .assert_lane v6, #12, #7, #35      // masked off, untouched
    .assert_lane v6, #13, #7, #36      // masked off, untouched
    vf.cmp.ge p1, v6, v2
    p.ballot s6, p1
    s.and    s6, s6, s5
    .assert_eq s6, #0x0f0f, #37       // the written lanes are in band
    vf.cmp.le p1, v6, v3
    p.ballot s6, p1
    s.and    s6, s6, s5
    .assert_eq s6, #0x0f0f, #38

    // ---- back to back, and an FP op straight after ----------------------
    .li      s1, #x_rcp
    v.ld.w   v1, [s1, #0]
    v.rcp.approx v4, v1
    v.rcp.approx v5, v4
    vf.add   v7, v5, v5
    vf.mul   v8, v5, v5
    // rcp(rcp(x)) is x to within two roundings; 2*that is within four.
    .li      s2, #lo_rt
    .li      s3, #hi_rt
    v.ld.w   v2, [s2, #0]
    v.ld.w   v3, [s3, #0]
    vf.cmp.ge p1, v7, v2
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #39
    vf.cmp.le p1, v7, v3
    p.ballot s4, p1
    .assert_eq s4, #0xffff, #40

    exit

